def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if request.get("command") == "quote":
        return quote(request)
    if request.get("command") == "total":
        return total(request)
    return {"error": "unknown_command"}

def test_quote_zero_charge(self):
    self.check_request(
        {
            "command": "quote",
            "line": {
                "line_id": "L-0",
                "account_id": "A",
                "subscription_id": "S",
                "service_on": "2026-05-01",
                "charge_cents": 0,
            },
        },
        {"release": "1.0", "credit_cents": 0, "amount_due_cents": 0, "line_id": "L-0"},
    )

def test_total_empty_statement(self):
    self.check_request(
        {"command": "total", "release": "1.0", "lines": []},
        {"release": "1.0", "credit_cents": 0, "amount_due_cents": 0},
    )

def test_total_quote_example_line(self):
    self.check_request(
        {
            "command": "total",
            "release": "1.0",
            "lines": [
                {
                    "line_id": "L-1",
                    "account_id": "A",
                    "subscription_id": "S",
                    "service_on": "2026-04-15",
                    "charge_cents": 19999,
                }
            ],
        },
        {"release": "1.0", "credit_cents": 1999, "amount_due_cents": 18000},
    )

def test_total_cap_spans_subscriptions_of_one_account(self):
    self.check_request(
        {
            "command": "total",
            "release": "1.0",
            "lines": [
                {
                    "line_id": "L-1",
                    "account_id": "A",
                    "subscription_id": "S1",
                    "service_on": "2026-04-01",
                    "charge_cents": 20000,
                },
                {
                    "line_id": "L-2",
                    "account_id": "A",
                    "subscription_id": "S2",
                    "service_on": "2026-04-01",
                    "charge_cents": 20000,
                },
            ],
        },
        {"release": "1.0", "credit_cents": 2400, "amount_due_cents": 37600},
    )

